			rows.Close()
			t.Fatal(err)
		}
		if seen[declaration] || versions[declaration] != version || status != "closed" || cardinality != 1 || cursor != 1 {
			rows.Close()
			t.Fatalf("two-pin feed disagrees with its exact pin: declaration=%q version=%q status=%q cursor=%d/%d", declaration, version, status, cursor, cardinality)
		}
		seen[declaration] = true
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		t.Fatal(err)
	}
	if err := rows.Close(); err != nil {
		t.Fatal(err)
	}
	if len(seen) != len(versions) {
		t.Fatalf("two-pin run has %d feeds, want %d", len(seen), len(versions))
	}
	for _, item := range []struct {
		name, query string
		want        int
	}{{"pins", `SELECT COUNT(*) FROM resource_version_pins WHERE run_id=$1`, 2}, {"outcomes", `SELECT COUNT(*) FROM fan_out_outcomes WHERE run_id=$1 AND outcome_kind='committed'`, 2}, {"source events", `SELECT COUNT(*) FROM events WHERE run_id=$1 AND event_name IN ('portfolio/account.registered','portfolio/account.notify.requested')`, 2}, {"pipeline receipts", `SELECT COUNT(*) FROM event_receipts r JOIN events e ON e.event_id=r.event_id WHERE e.run_id=$1 AND e.event_name IN ('portfolio/account.registered','portfolio/account.notify.requested') AND r.subscriber_type='platform' AND r.subscriber_id='pipeline' AND r.outcome='success'`, 2}, {"settled deliveries", `SELECT COUNT(*) FROM event_deliveries d JOIN events e ON e.event_id=d.event_id WHERE d.run_id=$1 AND e.event_name IN ('portfolio/account.registered','portfolio/account.notify.requested') AND d.status='delivered' AND d.continuation_handoff_at IS NOT NULL`, 2}, {"child instances", `SELECT COUNT(*) FROM flow_instances WHERE run_id=$1 AND flow_template='account'`, 2}} {
		var got int
