				t.Fatal(err)
			}
			if generationsAfter != generationsBefore || eventsAfter != 0 {
				t.Fatalf("empty restart resurrected work: generations=%d want=%d events=%d", generationsAfter, generationsBefore, eventsAfter)
			}
		})
	}
}

